import React from "react";

export default class Setting extends React.Component {
    render() {
        return (
            <>
                <h2>설정</h2>
                <>
                    <li>일반</li>
                    <li>보안</li>
                    <li>알림</li>
                    <li>채팅</li>
                    <li>화면</li>
                    <li>데이터 및 저장 공간</li>
                    <li>도움말</li>
                </>
                
            </>
        );
    }
}
